import{_ as e,o,c as a,a2 as i}from"./chunks/framework.BsgK4TUM.js";const u=JSON.parse('{"title":"Digital Downloads","description":"","frontmatter":{},"headers":[],"relativePath":"how-tos/digital.md","filePath":"how-tos/digital.md"}'),s={name:"how-tos/digital.md"};function n(l,t,r,d,c,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="digital-downloads" tabindex="-1">Digital Downloads <a class="header-anchor" href="#digital-downloads" aria-label="Permalink to &quot;Digital Downloads&quot;">​</a></h1><p>Each product within your store can have a digital download associated with it, a file selected from the file manager.</p><p>When that product is ordered, both the order completion page and the receipt email will receive a link to that file to download it.</p><p>When configuring a product to be a digital download:</p><ul><li>unless you are also shipping a physical good, change the Product is Shippable option to &#39;No&#39; against the product</li><li>set the <strong>Offer quantity selection</strong> option to <strong>No, only allow one of this product in the cart</strong></li><li>select a file from the file manager using the <strong>File to download on purchase</strong> option, on the Downloads and User Groups tab of a product.</li><li>check that your product has an appropriately configured stock level, such as unlimited</li></ul><div class="tip custom-block"><p class="custom-block-title">Download Links</p><p>Links to downloadable files are not _<em>direct</em> links to files, they are instead unique links specific to the order placed. These links expire after a number of hours (48 by default), to prevent hotlinking. This number of hours can be adjusted via the Digital Downloads tab of <strong>Store / Settings</strong>, using the <em>Number of hours before digital download links expiry</em> field.</p></div><p>If you intend that customers can return to your site and re-download files further into the future, with a list of digital downloads they have purchased displayed, it is suggested to create a protected page on your site, and use user accounts to control access.</p>',7)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
